import sys, json
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data.get('channels', []):
        name = ch.get('name','')
        if 'platform' in name.lower() or 'infra' in name.lower() or 'deploy' in name.lower() or 'devops' in name.lower() or 'sre' in name.lower():
            print(f\"{ch['id']} | {name} | {'private' if ch.get('is_private') else 'public'}\")
    print('---ALL CHANNELS---')
    for ch in data.get('channels', []):
        print(f\"{ch['id']} | {ch['name']}\")
